/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { AppliedUndef, E, Float, Pow, Rational, Sym, add, countOps, diff, factor, fn, mul, pow, simplify, symbols, trigsimp } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.vector.basisdependent", () => {
  it("diff(sin(x), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(fn('sin', [x], { evaluate: false }), x, 1))).toBe('cos(x)');
  });
  it("diff(f(x), x, x, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(diff(diff(new AppliedUndef('f', [x]), x, 1), x, 1), x, 1))).toBe('Derivative(f(x), (x, 3))');
  });
  it("diff(f(x), x, 3)", () => {
    const x = new Sym('x');
    expect(sympyStr(diff(new AppliedUndef('f', [x]), x, 3))).toBe('Derivative(f(x), (x, 3))');
  });
  it("diff(sin(x)*cos(y), x, 2, y, 2)", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(diff(diff(mul(fn('cos', [y], { evaluate: false }), fn('sin', [x], { evaluate: false })), x, 2), y, 2))).toBe('sin(x)*cos(y)');
  });
  it("diff(sin(x))", () => {
    const x = new Sym('x');
    const v1 = x;
    expect(sympyStr(diff(fn('sin', [v1], { evaluate: false }), v1))).toBe('cos(x)');
  });
  it("N(x, chop=True)", () => {
    expect(sympyStr(new Float(0.0001).evalf(15, { chop: true }))).toBe('0.000100000000000000');
  });
  it("N(x, chop=1e-5)", () => {
    expect(sympyStr(new Float(0.0001).evalf(15, { chop: 0.00001 }))).toBe('0.000100000000000000');
  });
  it("N(x, chop=1e-4)", () => {
    expect(sympyStr(new Float(0.0001).evalf(15, { chop: 0.0001 }))).toBe('0');
  });
  // the arguments do not type-check against the public API
  //   (x + y - z).subs(values)
  //   => 0
  it.todo("(x + y - z).subs(values)");
  // the arguments do not type-check against the public API
  //   (x + y - z).evalf(subs=values)
  //   => 1.00000000000000
  it.todo("(x + y - z).evalf(subs=values)");
  it("factor(2*x**5 + 2*x**4*y + 4*x**3 + 4*x**2*y + 2*x + 2*y)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(factor(add(mul(Rational.of(2n, 1n, { gcd: 1n }), x), mul(Rational.of(2n, 1n, { gcd: 1n }), y), mul(Rational.of(2n, 1n, { gcd: 1n }), pow(x, Rational.of(5n, 1n, { gcd: 1n }))), mul(Rational.of(4n, 1n, { gcd: 1n }), pow(x, Rational.of(3n, 1n, { gcd: 1n }))), mul(Rational.of(2n, 1n, { gcd: 1n }), y, pow(x, Rational.of(4n, 1n, { gcd: 1n }))), mul(Rational.of(4n, 1n, { gcd: 1n }), y, pow(x, Rational.of(2n, 1n, { gcd: 1n })))), { deep: false, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('2*(x + y)*(x**2 + 1)**2');
  });
  it("factor(x**2 + 1)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), { deep: false, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('x**2 + 1');
  });
  it("factor(x**2 + 1, modulus=2)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), { modulus: 2n, deep: false, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('(x + 1)**2');
  });
  it("factor(x**2 + 1, gaussian=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), { deep: false, gaussian: true, fraction: true, expand: true, gens: [] }))).toBe('(x - I)*(x + I)');
  });
  it("factor(x**2 - 2, extension=sqrt(2))", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(Rational.of(-2n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n }))), { extension: pow(Rational.of(2n, 1n, { gcd: 1n }), Rational.of(1n, 2n, { gcd: 1n })), deep: false, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('(x - sqrt(2))*(x + sqrt(2))');
  });
  it("factor((x**2 - 1)/(x**2 + 4*x + 4))", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(mul(pow(add(Rational.of(4n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n })), mul(Rational.of(4n, 1n, { gcd: 1n }), x)), Rational.of(-1n, 1n, { gcd: 1n })), add(Rational.of(-1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n })))), { deep: false, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('(x - 1)*(x + 1)/(x + 2)**2');
  });
  it("factor((x**2 + 4*x + 4)**10000000*(x**2 + 1))", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(mul(pow(add(Rational.of(4n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n })), mul(Rational.of(4n, 1n, { gcd: 1n }), x)), Rational.of(10000000n, 1n, { gcd: 1n })), add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n })))), { deep: false, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('(x + 2)**20000000*(x**2 + 1)');
  });
  it("factor(eq)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(pow(Rational.of(2n, 1n, { gcd: 1n }), add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n })), mul(Rational.of(2n, 1n, { gcd: 1n }), x))), { deep: false, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('2**(x**2 + 2*x + 1)');
  });
  it("factor(eq, deep=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(pow(Rational.of(2n, 1n, { gcd: 1n }), add(Rational.of(1n, 1n, { gcd: 1n }), pow(x, Rational.of(2n, 1n, { gcd: 1n })), mul(Rational.of(2n, 1n, { gcd: 1n }), x))), { deep: true, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('2**((x + 1)**2)');
  });
  it("factor(5*x + 3*exp(2 - 7*x), deep=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(mul(Rational.of(3n, 1n, { gcd: 1n }), new Pow(E, add(Rational.of(2n, 1n, { gcd: 1n }), mul(Rational.of(-7n, 1n, { gcd: 1n }), x)))), mul(Rational.of(5n, 1n, { gcd: 1n }), x)), { deep: true, gaussian: false, fraction: true, expand: true, gens: [] }))).toBe('(5*x*exp(7*x) + 3*exp(2))*exp(-7*x)');
  });
  it("factor(5*x + 3*exp(2 - 7*x), deep=True, fraction=False)", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(mul(Rational.of(3n, 1n, { gcd: 1n }), new Pow(E, add(Rational.of(2n, 1n, { gcd: 1n }), mul(Rational.of(-7n, 1n, { gcd: 1n }), x)))), mul(Rational.of(5n, 1n, { gcd: 1n }), x)), { deep: true, gaussian: false, fraction: false, expand: true, gens: [] }))).toBe('5*x + 3*exp(2)*exp(-7*x)');
  });
  it("simplify(a)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(simplify(mul(pow(add(mul(x, pow(fn('cos', [y], { evaluate: false }), Rational.of(2n, 1n, { gcd: 1n }))), mul(x, pow(fn('sin', [y], { evaluate: false }), Rational.of(2n, 1n, { gcd: 1n })))), Rational.of(-1n, 1n, { gcd: 1n })), add(x, pow(x, Rational.of(2n, 1n, { gcd: 1n })))), { inverse: false, rational: false, doit: true }))).toBe('x + 1');
  });
  it("trigsimp(a)", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(trigsimp(mul(pow(add(mul(x, pow(fn('cos', [y], { evaluate: false }), Rational.of(2n, 1n, { gcd: 1n }))), mul(x, pow(fn('sin', [y], { evaluate: false }), Rational.of(2n, 1n, { gcd: 1n })))), Rational.of(-1n, 1n, { gcd: 1n })), add(x, pow(x, Rational.of(2n, 1n, { gcd: 1n })))), { old: false, deep: false, inverse: false }))).toBe('(x**2 + x)/x');
  });
  it("simplify(root, ratio=1) == root", () => {
    expect(sympyStr(pow(add(Rational.of(3n, 1n, { gcd: 1n }), pow(Rational.of(2n, 1n, { gcd: 1n }), Rational.of(1n, 2n, { gcd: 1n }))), Rational.of(-1n, 1n, { gcd: 1n })).equals(pow(add(Rational.of(3n, 1n, { gcd: 1n }), pow(Rational.of(2n, 1n, { gcd: 1n }), Rational.of(1n, 2n, { gcd: 1n }))), Rational.of(-1n, 1n, { gcd: 1n }))))).toBe('True');
  });
  it("count_ops(g)", () => {
    const a = new Sym('a', { positive: true });
    const b = new Sym('b', { positive: true });
    expect(sympyStr(countOps(add(mul(fn('log', [a], { evaluate: false }), fn('log', [pow(b, Rational.of(-1n, 1n, { gcd: 1n }))], { evaluate: false })), fn('log', [a], { evaluate: false }), fn('log', [b], { evaluate: false }))))).toBe('8');
  });
  it("count_ops(h)", () => {
    const a = new Sym('a', { positive: true });
    const b = new Sym('b', { positive: true });
    expect(sympyStr(countOps(fn('log', [mul(a, pow(b, add(Rational.of(1n, 1n, { gcd: 1n }), mul(Rational.of(-1n, 1n, { gcd: 1n }), fn('log', [a], { evaluate: false })))))], { evaluate: false })))).toBe('5');
  });
  // text that is not a string
  //   print(count_ops(g, visual=True))
  //   => 2*ADD + DIV + 4*LOG + MUL
  it.todo("print(count_ops(g, visual=True))");
  // text that is not a string
  //   print(count_ops(h, visual=True))
  //   => 2*LOG + MUL + POW + SUB
  it.todo("print(count_ops(h, visual=True))");
  // no value
  //   simplify(g, measure=my_measure)
  //   => -log(a)*log(b) + log(a) + log(b)
  it.todo("simplify(g, measure=my_measure)");
  it("trigsimp(e)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(add(mul(Rational.of(2n, 1n, { gcd: 1n }), pow(fn('cos', [x], { evaluate: false }), Rational.of(2n, 1n, { gcd: 1n }))), mul(Rational.of(2n, 1n, { gcd: 1n }), pow(fn('sin', [x], { evaluate: false }), Rational.of(2n, 1n, { gcd: 1n })))), { old: false, deep: false, inverse: false }))).toBe('2');
  });
  it("trigsimp(log(e))", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(fn('log', [add(mul(Rational.of(2n, 1n, { gcd: 1n }), pow(fn('cos', [x], { evaluate: false }), Rational.of(2n, 1n, { gcd: 1n }))), mul(Rational.of(2n, 1n, { gcd: 1n }), pow(fn('sin', [x], { evaluate: false }), Rational.of(2n, 1n, { gcd: 1n }))))], { evaluate: false }), { old: false, deep: false, inverse: false }))).toBe('log(2)');
  });
  it("trigsimp(t, method='old') == t", () => {
    const x = new Sym('x');
    expect(sympyStr(add(mul(Rational.of(-2n, 1n, { gcd: 1n }), pow(fn('coth', [x], { evaluate: false }), Rational.of(-7n, 1n, { gcd: 1n }))), mul(Rational.of(3n, 1n, { gcd: 1n }), pow(fn('tanh', [x], { evaluate: false }), Rational.of(7n, 1n, { gcd: 1n })))).equals(add(mul(Rational.of(-2n, 1n, { gcd: 1n }), pow(fn('coth', [x], { evaluate: false }), Rational.of(-7n, 1n, { gcd: 1n }))), mul(Rational.of(3n, 1n, { gcd: 1n }), pow(fn('tanh', [x], { evaluate: false }), Rational.of(7n, 1n, { gcd: 1n }))))))).toBe('True');
  });
  it("trigsimp(t)", () => {
    const x = new Sym('x');
    expect(sympyStr(trigsimp(add(mul(Rational.of(-2n, 1n, { gcd: 1n }), pow(fn('coth', [x], { evaluate: false }), Rational.of(-7n, 1n, { gcd: 1n }))), mul(Rational.of(3n, 1n, { gcd: 1n }), pow(fn('tanh', [x], { evaluate: false }), Rational.of(7n, 1n, { gcd: 1n })))), { old: false, deep: false, inverse: false }))).toBe('tanh(x)**7');
  });
  it("h", () => {
    const a = new Sym('a', { positive: true });
    const b = new Sym('b', { positive: true });
    expect(sympyStr(simplify(add(mul(fn('log', [a], { evaluate: false }), fn('log', [pow(b, Rational.of(-1n, 1n, { gcd: 1n }))], { evaluate: false })), fn('log', [a], { evaluate: false }), fn('log', [b], { evaluate: false })), { inverse: false, rational: false, doit: true }))).toBe('log(a*b**(1 - log(a)))');
  });
});
